package com.taller.portal.service;
import com.taller.portal.dto.AuthDtos.*; import com.taller.portal.model.*; import com.taller.portal.repository.*; import org.springframework.security.crypto.password.PasswordEncoder; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional;
@Service public class AuthService { private final UserRepository users; private final RoleRepository roles; private final PasswordEncoder encoder; private final JwtService jwt;
 public AuthService(UserRepository u,RoleRepository r,PasswordEncoder e,JwtService j){users=u;roles=r;encoder=e;jwt=j;}
 public AuthResponse login(Login in){User u=users.findByEmail(in.email().trim().toLowerCase()).orElseThrow(()->new IllegalArgumentException("Credenciales incorrectas"));if(!u.activo||!encoder.matches(in.password(),u.passwordHash))throw new IllegalArgumentException("Credenciales incorrectas");u.ultimoAcceso=java.time.LocalDateTime.now();users.save(u);return response(u);}
 @Transactional public AuthResponse register(Register in){String email=in.email().trim().toLowerCase();if(users.existsByEmail(email)||users.existsByCelular(in.celular().trim()))throw new IllegalArgumentException("El correo o celular ya está registrado");User u=new User();u.nombre=in.nombre().trim();u.email=email;u.celular=in.celular().trim();u.passwordHash=encoder.encode(in.password());u.rol=roles.findByNombre(RoleName.CLIENTE).orElseThrow();users.save(u);return response(u);}
 public void recover(Recovery in){User u=users.findByEmailOrCelular(in.identificador().trim().toLowerCase(),in.identificador().trim()).orElseThrow(()->new IllegalArgumentException("No encontramos una cuenta con esos datos"));u.passwordHash=encoder.encode(in.nuevaPassword());users.save(u);}
 private AuthResponse response(User u){return new AuthResponse(jwt.generate(u.email,u.rol.nombre.name()),u.nombre,u.email,u.rol.nombre.name());}}
